// Generated by create-pet-skill — desktop pet main process
const { app, BrowserWindow, ipcMain, Menu, screen, globalShortcut, Tray, nativeImage, Notification } = require('electron');
const path = require('path');
const fs = require('fs');
const http = require('http');
const crypto = require('crypto');
const runtime = require('./runtime');

// ---- baked constants ----
const APP_NAME = __APP_NAME__;
const STAGE_WIDTH = __STAGE_WIDTH__;
const STAGE_HEIGHT = __STAGE_HEIGHT__;
const HAS_ACTION = __HAS_ACTION__;
const DEFAULT_PERSONA = __DEFAULT_PERSONA__;

app.setName(APP_NAME); // keep userData path stable between dev and packaged runs
// 透明置顶小窗口走软件渲染即可；部分 Windows 环境 GPU 进程会在启动/缩放重绘时崩溃弹窗
app.disableHardwareAcceleration();

// ---- optional native modules (graceful degradation, never crash) ----
let uiohook = null;
try {
  uiohook = require('uiohook-napi');
  // uiohook-napi exports { uIOhook, UiohookKey } — normalize to the instance
  uiohook = uiohook.uIOhook || uiohook;
} catch (e) {
  console.warn('[pet] uiohook-napi 不可用，键盘/鼠标镜像与全局视线跟随将降级：', e.message);
}
// ---- small utils ----
function clamp(v, min, max) {
  return Math.min(max, Math.max(min, v));
}

function debounce(fn, ms) {
  let t = null;
  return function () {
    const args = arguments;
    if (t) clearTimeout(t);
    t = setTimeout(function () { t = null; fn.apply(null, args); }, ms);
  };
}

// ---- settings store (userData) ----
const userDataDir = app.getPath('userData');

// ---- 错误日志：未捕获异常默认会弹「A JavaScript error occurred」对话框，
// 这里拦截后写入 userData/error.log（含完整堆栈），既不打扰用户又能排查问题
function logError(tag, err) {
  try {
    const line = '[' + new Date().toISOString() + '] ' + tag + '\n' + (err && err.stack ? err.stack : String(err)) + '\n\n';
    fs.appendFileSync(path.join(userDataDir, 'error.log'), line);
  } catch (e) { /* ignore */ }
}
process.on('uncaughtException', function (err) {
  logError('uncaughtException', err);
  console.error('[pet] uncaughtException:', err && err.stack ? err.stack : err);
});
process.on('unhandledRejection', function (err) {
  logError('unhandledRejection', err);
  console.error('[pet] unhandledRejection:', err);
});
app.on('child-process-gone', function (_e, details) {
  if (details && details.reason === 'clean-exit') return;
  logError('child-process-gone', JSON.stringify(details));
});

// 启动步骤日志：主进程卡在哪一步，error.log 里一眼可见
function logStep(msg) {
  logError('step', msg);
}

// 渲染进程崩溃/加载失败/报错 → error.log（这类错误默认静默不可见）
function attachErrorCapture(win, tag) {
  if (!win || win.isDestroyed()) return;
  win.webContents.on('render-process-gone', function (_e, details) {
    logError(tag + ':render-process-gone', JSON.stringify(details));
  });
  win.webContents.on('did-fail-load', function (_e, code, desc, url) {
    logError(tag + ':did-fail-load', code + ' ' + desc + ' ' + url);
  });
  win.webContents.on('console-message', function (_e, level, message, line, sourceId) {
    if (level >= 3) logError(tag + ':console', message + ' (' + sourceId + ':' + line + ')');
  });
}

// 单实例：重复双击启动.bat 时直接退出新实例，避免多开互相抢快捷键/输入钩子
// （放在 logError 之后，退出前能留一行日志）
if (!app.requestSingleInstanceLock()) {
  logStep('second-instance-exit');
  console.log('[pet] 已在运行，本次启动自动退出');
  process.exit(0);
}
app.on('second-instance', function () {
  logStep('second-instance-event');
  if (petWindow && !petWindow.isDestroyed()) petWindow.show();
});
logStep('app-start pid=' + process.pid);
const DEFAULT_SETTINGS = {
  version: 1,
  autoScaleRatio: 0.2,
  zoom: 1,
  opacity: 1,
  inputMirror: true,
  position: null,
};

function loadJson(name, fallback) {
  try {
    const p = path.join(userDataDir, name);
    if (!fs.existsSync(p)) return fallback;
    return Object.assign({}, fallback, JSON.parse(fs.readFileSync(p, 'utf-8')));
  } catch (e) {
    try {
      fs.renameSync(path.join(userDataDir, name), path.join(userDataDir, name + '.bak'));
    } catch (e2) { /* ignore */ }
    return fallback;
  }
}

let settings = loadJson('settings.json', DEFAULT_SETTINGS);
let pendingSettingsSave = null;

function saveSettings() {
  if (pendingSettingsSave) return;
  pendingSettingsSave = setTimeout(function () {
    pendingSettingsSave = null;
    try {
      fs.mkdirSync(userDataDir, { recursive: true });
      fs.writeFileSync(path.join(userDataDir, 'settings.json'), JSON.stringify(settings, null, 2));
    } catch (e) {
      console.warn('[pet] 设置写入失败：', e.message);
    }
  }, 500);
}

function broadcastSettings() {
  saveSettings();
  if (petWindow && !petWindow.isDestroyed()) {
    petWindow.webContents.send('settings-changed', settings);
  }
}

// ---- windows ----
let petWindow = null;
let chatWindow = null;
let tray = null;
const aiRequests = new Map();
let petActionId = null;
let lastDisplayKey = null;

// Same formula as the renderer's — used only to pre-size the window at startup
function computeScale(workAreaHeight, s) {
  const ratio = clamp(s.autoScaleRatio != null ? s.autoScaleRatio : 0.2, 0.08, 0.45);
  const targetH = clamp(workAreaHeight * ratio, 80, Math.min(420, workAreaHeight * 0.5));
  return (targetH * clamp(s.zoom != null ? s.zoom : 1, 0.5, 2.5)) / STAGE_HEIGHT;
}

function restorePosition(width, height) {
  const pos = settings.position;
  let d = null;
  if (pos && pos.displayId) {
    d = screen.getAllDisplays().find(function (dd) { return dd.id === pos.displayId; }) || null;
  }
  if (!d) d = screen.getPrimaryDisplay();
  const wa = d.workArea;
  let x, y;
  if (pos && pos.rx != null && pos.ry != null) {
    x = wa.x + pos.rx * Math.max(wa.width - width, 1);
    y = wa.y + pos.ry * Math.max(wa.height - height, 1);
  } else {
    x = wa.x + wa.width - width - 80;
    y = wa.y + Math.round(wa.height * 0.55);
  }
  return { x: Math.round(x), y: Math.round(y), displayId: d.id };
}

// getDisplayMatching 在个别 Windows 环境（启动瞬间/DPI 变化时）会抛
// 「Error processing argument at index 0, conversion failure」——捕获后回退主显示器，
// 现场写进 error.log，不再弹系统错误对话框
function safeDisplayMatching(bounds) {
  try {
    // getDisplayMatching 要求整数参数：渲染层算出的坐标常带 .5 小数（窗口居中除 2），
    // 直接传入会抛「conversion failure」——先取整
    return screen.getDisplayMatching({
      x: Math.round(Number(bounds.x) || 0),
      y: Math.round(Number(bounds.y) || 0),
      width: Math.round(Number(bounds.width) || 0),
      height: Math.round(Number(bounds.height) || 0),
    });
  } catch (e) {
    logError('getDisplayMatching failed, bounds=' + JSON.stringify(bounds), e);
    return screen.getPrimaryDisplay();
  }
}

function clampToWorkArea(b) {
  // 参数先做数值化防护：渲染层可能传入非法值，直接进原生 API 会弹「conversion failure」报错
  const x0 = Number(b.x);
  const y0 = Number(b.y);
  const w0 = Number(b.width) || STAGE_WIDTH;
  const h0 = Number(b.height) || STAGE_HEIGHT;
  const d = safeDisplayMatching({ x: isFinite(x0) ? x0 : 0, y: isFinite(y0) ? y0 : 0, width: w0, height: h0 });
  const wa = d.workArea;
  const x = clamp(isFinite(x0) ? x0 : 0, wa.x - w0 + 40, wa.x + wa.width - 40);
  let y;
  if (wa.height - 40 < h0) {
    y = wa.y;
  } else {
    y = clamp(isFinite(y0) ? y0 : 0, wa.y, wa.y + wa.height - 40);
  }
  return { x: Math.round(x), y: Math.round(y), width: w0, height: h0 };
}

function createWindow() {
  let d = null;
  if (settings.position && settings.position.displayId) {
    d = screen.getAllDisplays().find(function (dd) { return dd.id === settings.position.displayId; }) || null;
  }
  if (!d) d = screen.getPrimaryDisplay();
  const scale = computeScale(d.workArea.height, settings);
  const width = Math.round(STAGE_WIDTH * scale);
  const height = Math.round(STAGE_HEIGHT * scale);
  const pos = restorePosition(width, height);
  petWindow = new BrowserWindow({
    x: pos.x, y: pos.y,
    width: width, height: height,
    transparent: true, frame: false, alwaysOnTop: true,
    // 不进任务栏：桌宠由托盘管理
    skipTaskbar: true, resizable: false, hasShadow: false,
    // type: 'toolbar' -> WS_EX_TOOLWINDOW，彻底不进 alt+tab（skipTaskbar 只管任务栏），
    // 从根源上消除「退出后 alt+tab 残留桌宠窗口」的幽灵条目
    type: 'toolbar',
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true, nodeIntegration: false,
    },
  });
  petWindow.loadFile(path.join(__dirname, 'renderer', 'index.html'));
  attachErrorCapture(petWindow, 'pet');
  petWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  petWindow.setAlwaysOnTop(true, 'screen-saver');
  petWindow.on('closed', function () { petWindow = null; });
  petWindow.on('move', debounce(function () { checkDisplayChange(); savePosition(); }, 300));
}

function createChatWindow() {
  if (chatWindow && !chatWindow.isDestroyed()) {
    chatWindow.show();
    chatWindow.focus();
    return;
  }
  chatWindow = new BrowserWindow({
    width: 720,
    height: 760,
    minWidth: 420,
    minHeight: 520,
    title: APP_NAME + ' AI',
    backgroundColor: '#181a22',
    webPreferences: { preload: path.join(__dirname, 'preload.js'), contextIsolation: true, nodeIntegration: false },
  });
  chatWindow.loadFile(path.join(__dirname, 'renderer', 'chat.html'), { query: { petName: APP_NAME } });
  attachErrorCapture(chatWindow, 'chat');
  chatWindow.on('closed', function () {
    const senderId = chatWindow && chatWindow.webContents.id;
    for (const request of aiRequests.values()) {
      if (request.senderId === senderId) request.controller.abort();
    }
    chatWindow = null;
  });
}

function currentDisplayConfig() {
  const d = petWindow ? safeDisplayMatching(petWindow.getBounds()) : screen.getPrimaryDisplay();
  return {
    displayId: d.id,
    workArea: { x: d.workArea.x, y: d.workArea.y, width: d.workArea.width, height: d.workArea.height },
    scaleFactor: d.scaleFactor,
  };
}

function checkDisplayChange() {
  const cfg = currentDisplayConfig();
  const key = cfg.displayId + ':' + cfg.workArea.width + 'x' + cfg.workArea.height;
  if (key !== lastDisplayKey) {
    lastDisplayKey = key;
    if (petWindow && !petWindow.isDestroyed()) {
      petWindow.webContents.send('display-config-changed', cfg);
    }
  }
}

function savePosition() {
  if (!petWindow || petWindow.isDestroyed()) return;
  const [x, y] = petWindow.getPosition();
  const [w, h] = petWindow.getSize();
  const d = safeDisplayMatching({ x: x, y: y, width: w, height: h });
  const wa = d.workArea;
  settings.position = {
    displayId: d.id,
    rx: (x - wa.x) / Math.max(wa.width - w, 1),
    ry: (y - wa.y) / Math.max(wa.height - h, 1),
  };
  saveSettings();
}

// ---- context menu ----
function sendCommand(cmd) {
  if (petWindow && !petWindow.isDestroyed()) {
    petWindow.webContents.send('pet-command', cmd);
  }
}

function applyOpacity() {
  if (petWindow && !petWindow.isDestroyed()) {
    petWindow.setOpacity(settings.opacity);
  }
}

function setOpacity(v) {
  settings.opacity = clamp(v, 0.3, 1);
  broadcastSettings();
  applyOpacity();
}

function resetPosition() {
  if (!petWindow || petWindow.isDestroyed()) return;
  const wa = screen.getPrimaryDisplay().workArea;
  const [w, h] = petWindow.getSize();
  petWindow.setBounds(clampToWorkArea({ x: wa.x + wa.width - w - 80, y: wa.y + wa.height - h - 40, width: w, height: h }));
  savePosition();
}

function toggleVisible() {
  if (!petWindow || petWindow.isDestroyed()) return;
  if (petWindow.isVisible()) {
    petWindow.hide();
  } else {
    petWindow.show();
  }
}

function createContextMenu(currentActionId) {
  const items = [
    { label: 'AI 工作台', click: createChatWindow },
    { type: 'separator' },
  ];
  const actions = __ACTION_MENU_ITEMS__;
  items.push(...actions.map(function (a) {
    return {
      label: a.id === currentActionId ? '\u2713 ' + a.label : a.label,
      click: function () {
        if (petWindow) petWindow.webContents.send('switch-action', a.id);
      },
    };
  }));
  items.push({ type: 'separator' });
  items.push({ label: '放大 (Ctrl+Shift+\u2192)', click: function () { sendCommand('zoom-in'); } });
  items.push({ label: '缩小 (Ctrl+Shift+\u2190)', click: function () { sendCommand('zoom-out'); } });
  items.push({ label: '恢复默认大小', click: function () { settings.zoom = 1; broadcastSettings(); } });
  items.push({ type: 'separator' });
  items.push({ label: '\u9000\u51fa', click: function () { app.quit(); } });
  return Menu.buildFromTemplate(items);
}

// ---- tray icon (fallback entry: show/hide + quit) ----
function createTray() {
  try {
    const iconPath = path.join(__dirname, 'assets', 'icon.png');
    const img = nativeImage.createFromPath(iconPath);
    const small = img.isEmpty() ? img : img.resize({ width: 16, height: 16 });
    tray = new Tray(small);
    tray.setToolTip(APP_NAME);
    tray.setContextMenu(Menu.buildFromTemplate([
      { label: '显示/隐藏', click: toggleVisible },
      { label: 'AI \u5de5\u4f5c\u53f0', click: createChatWindow },
      { type: 'separator' },
      { label: '\u9000\u51fa', click: function () { app.quit(); } },
    ]));
    tray.on('click', toggleVisible);
  } catch (e) {
    console.warn('[pet] 托盘创建失败：', e.message);
  }
}

// ---- global input mirror (uiohook) ----
function initInputCapture() {
  if (!uiohook || !settings.inputMirror) return;
  let lastKeySentAt = 0;
  let lastKeyEventAt = 0;
  let lastClickSentAt = 0;
  try {
    uiohook.on('keydown', function () {
      // 键盘镜像直接发给桌宠本体：敲键盘 -> 她切到「敲键盘」动作；持续输入期间每 1 秒补发一次，动画不间断
      const now = Date.now();
      if (now - lastKeyEventAt > 2000) lastKeySentAt = 0; // typing paused 2s -> reset cooldown
      lastKeyEventAt = now;
      if (now - lastKeySentAt >= 1000 && petWindow && !petWindow.isDestroyed()) {
        lastKeySentAt = now;
        petWindow.webContents.send('input-event', { type: 'keydown' });
      }
    });
    uiohook.on('keyup', function () {
      lastKeyEventAt = Date.now();
    });
    uiohook.on('mousedown', function (e) {
      const now = Date.now();
      if (now - lastClickSentAt < 3000 || !petWindow || petWindow.isDestroyed()) return;
      // 点在桌宠窗口上的点击由它自己的事件处理，不镜像
      if (clickInsideWindow(e, petWindow)) return;
      lastClickSentAt = now;
      petWindow.webContents.send('input-event', { type: 'mouse-down', button: e.button });
    });
    // 眼神跟随：全局鼠标位置 40ms 节流，发相对窗口中心的偏移给渲染层算注视方向
    let lastMoveSentAt = 0;
    uiohook.on('mousemove', function (e) {
      const now = Date.now();
      if (now - lastMoveSentAt < 40 || !petWindow || petWindow.isDestroyed()) return;
      lastMoveSentAt = now;
      const b = petWindow.getBounds();
      petWindow.webContents.send('pointer-move', {
        dx: e.x - (b.x + b.width / 2),
        dy: e.y - (b.y + b.height / 2),
      });
    });
    uiohook.start();
    console.log('[pet] 输入镜像已启用');
  } catch (e) {
    console.warn('[pet] 输入镜像启动失败：', e.message);
    uiohook = null;
  }
}

function clickInsideWindow(e, win) {
  if (!win || win.isDestroyed()) return false;
  const b = win.getBounds();
  return e.x >= b.x && e.x <= b.x + b.width && e.y >= b.y && e.y <= b.y + b.height;
}

// ---- IPC ----
ipcMain.on('show-context-menu', function (_event, currentActionId) {
  const menu = createContextMenu(currentActionId);
  menu.popup({ window: petWindow });
});

ipcMain.on('resize-window', function (_event, width, height) {
  if (!petWindow) return;
  width = Number(width);
  height = Number(height);
  if (!isFinite(width) || !isFinite(height) || width <= 0 || height <= 0) return;
  const [x, y] = petWindow.getPosition();
  const [w, h] = petWindow.getSize();
  // horizontal centering + bottom anchor (feet stay put, no jumping)
  petWindow.setBounds(clampToWorkArea({
    x: x + (w - width) / 2,
    y: y + (h - height),
    width: Math.round(width),
    height: Math.round(height),
  }));
});

ipcMain.on('move-window', function (_event, dx, dy, opts) {
  if (!petWindow) return;
  dx = Number(dx);
  dy = Number(dy);
  if (!isFinite(dx) || !isFinite(dy)) return;
  const [x, y] = petWindow.getPosition();
  let nx = x + dx;
  let ny = y + dy;
  if (opts && opts.clamp) {
    const [w, h] = petWindow.getSize();
    const b = clampToWorkArea({ x: nx, y: ny, width: w, height: h });
    nx = b.x;
    ny = b.y;
  }
  petWindow.setPosition(Math.round(nx), Math.round(ny));
});

ipcMain.handle('move-window-with-collision', function (_event, dx, dy) {
  if (!petWindow || petWindow.isDestroyed()) return { hitX: false, hitY: false };
  dx = Number(dx);
  dy = Number(dy);
  if (!isFinite(dx) || !isFinite(dy)) return { hitX: false, hitY: false };
  const [x, y] = petWindow.getPosition();
  const [w, h] = petWindow.getSize();
  const targetX = x + dx;
  const targetY = y + dy;
  const bounded = clampToWorkArea({ x: targetX, y: targetY, width: w, height: h });
  petWindow.setPosition(bounded.x, bounded.y);
  return {
    hitX: bounded.x !== Math.round(targetX),
    hitY: bounded.y !== Math.round(targetY),
  };
});

ipcMain.handle('get-display-config', function () {
  return currentDisplayConfig();
});

ipcMain.handle('settings-get', function () {
  return settings;
});

ipcMain.on('settings-set', function (_event, patch) {
  if (!patch || typeof patch !== 'object') return;
  for (const k of Object.keys(patch)) settings[k] = patch[k];
  broadcastSettings();
});

ipcMain.handle('capabilities-get', function () {
  return {
    inputCapture: !!uiohook,
    opacity: settings.opacity,
  };
});

ipcMain.on('pet-action-state', function (event, actionId) {
  if (!petWindow || event.sender.id !== petWindow.webContents.id) return;
  if (typeof actionId === 'string' && HAS_ACTION[actionId]) petActionId = actionId;
});

// AI 工作空间 = 桌宠所在目录（打包后为 isla.exe 所在目录）：每个桌宠的会话/记忆/技能/附件/工具数据互相独立
const workspaceRoot = app.isPackaged ? path.dirname(app.getPath('exe')) : __dirname;
ipcMain.handle('ai-settings-get', function () { return runtime.getSettings(workspaceRoot); });
ipcMain.handle('ai-settings-set', function (_event, patch) { return runtime.saveSettings(workspaceRoot, patch); });
ipcMain.handle('ai-sessions-list', function () { return runtime.listSessions(workspaceRoot); });
ipcMain.handle('ai-session-get', function (_event, id) { return runtime.loadSession(workspaceRoot, id); });
ipcMain.handle('ai-session-save', function (_event, session) { return runtime.saveSession(workspaceRoot, session); });
ipcMain.handle('ai-session-delete', function (_event, id) { return runtime.deleteSession(workspaceRoot, id); });
ipcMain.handle('ai-soul-get', function () { return runtime.loadSoul(workspaceRoot); });
ipcMain.handle('ai-soul-set', function (_event, content) { return runtime.saveSoul(workspaceRoot, content); });
ipcMain.handle('ai-skills-list', function () { return runtime.listSkills(workspaceRoot); });
ipcMain.handle('ai-skill-get', function (_event, name) { return runtime.loadSkill(workspaceRoot, name); });
ipcMain.handle('ai-attachment-save', function (_event, name, mediaType, dataBase64) { return runtime.saveAttachment(workspaceRoot, name, mediaType, dataBase64); });
ipcMain.handle('ai-tool-run', function (_event, tool, action, params) { return runtime.runTool(workspaceRoot, tool, action, params || {}); });
ipcMain.handle('ai-memory-list', function () { return runtime.listMemory(workspaceRoot); });
ipcMain.handle('ai-memory-add', function (_event, content) { return runtime.addMemory(workspaceRoot, content, 'user'); });
// 流式对话：渲染层发 ai-chat-send，主进程把增量事件推回 ai-chat-event（chunk/tool/done/error）
ipcMain.on('ai-chat-send', function (event, payload) {
  const p = payload || {};
  const requestId = p.requestId || String(Date.now());
  const senderId = event.sender.id;
  const controller = new AbortController();
  aiRequests.set(requestId, { senderId: senderId, controller: controller });
  const emit = function (ev) {
    if (chatWindow && !chatWindow.isDestroyed() && chatWindow.webContents.id === senderId) {
      chatWindow.webContents.send('ai-chat-event', Object.assign({ requestId: requestId }, ev));
    }
  };
  runtime.askAi(workspaceRoot, p.prompt || '', p.attachments || [], p.history || [], emit, DEFAULT_PERSONA, controller.signal)
    .then(function (res) {
      emit({ type: 'done', text: res.text });
      sendPetEvent({ type: 'say', text: res.text });
    })
    .catch(function (e) {
      if (controller.signal.aborted) emit({ type: 'cancelled' });
      else emit({ type: 'error', message: String(e && e.message ? e.message : e) });
    })
    .finally(function () { aiRequests.delete(requestId); });
});
ipcMain.on('ai-chat-cancel', function (event, requestId) {
  const request = aiRequests.get(requestId);
  if (request && request.senderId === event.sender.id) request.controller.abort();
});
// 系统通知 + 桌宠事件（番茄钟完成等 → 桌宠切「消息提醒」动作）
function notifyPet(title, body, type) {
  try {
    if (Notification.isSupported()) new Notification({ title: String(title || ''), body: String(body || '').slice(0, 200) }).show();
  } catch (e) { /* ignore */ }
  if (petWindow && !petWindow.isDestroyed()) {
    petWindow.webContents.send('pet-event', { type: type || 'notify', title: title, body: body });
  }
}
function sendPetEvent(event) {
  if (petWindow && !petWindow.isDestroyed()) petWindow.webContents.send('pet-event', event);
}
ipcMain.on('notify', function (_event, opts) { notifyPet((opts && opts.title) || '', (opts && opts.body) || '', opts && opts.type); });
ipcMain.on('open-ai-window', createChatWindow);

// Optional local bridge for AstrBot and other trusted local clients.
// It is disabled unless ISLA_BRIDGE_TOKEN is explicitly configured.
const bridgeToken = String(process.env.ISLA_BRIDGE_TOKEN || '');
const bridgePort = Number(process.env.ISLA_BRIDGE_PORT || 43123);
const bridgeQueues = new Map();
const bridgeRate = new Map();
let bridgeServer = null;

function bridgeJson(res, status, value) {
  const body = JSON.stringify(value);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(body),
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
  });
  res.end(body);
}

function bridgeAuthorized(req) {
  const header = String(req.headers.authorization || '');
  if (!header.startsWith('Bearer ')) return false;
  const supplied = Buffer.from(header.slice(7));
  const expected = Buffer.from(bridgeToken);
  return supplied.length === expected.length && crypto.timingSafeEqual(supplied, expected);
}

function bridgeReadBody(req) {
  return new Promise(function (resolve, reject) {
    let body = '';
    req.on('data', function (chunk) {
      body += chunk;
      if (Buffer.byteLength(body) > 32 * 1024) {
        reject(new Error('请求体超过 32KB 限制'));
        req.destroy();
      }
    });
    req.on('end', function () {
      if (!body) return resolve({});
      try { resolve(JSON.parse(body)); } catch (e) { reject(new Error('请求体必须是合法 JSON')); }
    });
    req.on('error', reject);
  });
}

function bridgeRateLimited(req) {
  const key = req.socket.remoteAddress || 'local';
  const now = Date.now();
  const entry = bridgeRate.get(key) || { start: now, count: 0 };
  if (now - entry.start >= 60_000) { entry.start = now; entry.count = 0; }
  entry.count += 1;
  bridgeRate.set(key, entry);
  if (bridgeRate.size > 32) {
    for (const [address, record] of bridgeRate) if (now - record.start >= 60_000) bridgeRate.delete(address);
  }
  return entry.count > 30;
}

function bridgeSessionId(value) {
  const id = String(value || '').trim();
  if (!id || id.length > 120 || !/^[\w.:@-]+$/.test(id)) {
    throw new Error('sessionId 必须是 1 到 120 位的字母、数字或 . : @ - _');
  }
  return 'bridge-' + id;
}

function queuedBridgeChat(sessionId, task) {
  const previous = bridgeQueues.get(sessionId) || Promise.resolve();
  const current = previous.catch(function () {}).then(task);
  bridgeQueues.set(sessionId, current);
  return current.finally(function () {
    if (bridgeQueues.get(sessionId) === current) bridgeQueues.delete(sessionId);
  });
}

async function bridgeChat(body) {
  const sessionId = bridgeSessionId(body.sessionId);
  const prompt = String(body.text || '').trim();
  if (!prompt) throw new Error('text 不能为空');
  if (prompt.length > 8000) throw new Error('text 不能超过 8000 字符');

  return queuedBridgeChat(sessionId, async function () {
    const session = runtime.loadSession(workspaceRoot, sessionId);
    const history = (session.messages || []).filter(function (m) {
      return m && (m.role === 'user' || m.role === 'assistant') && m.content;
    }).slice(-40);
    const result = await runtime.askAi(workspaceRoot, prompt, [], history, null, DEFAULT_PERSONA);
    session.messages = history.concat([
      { role: 'user', content: prompt, createdAt: Date.now() },
      { role: 'assistant', content: result.text, createdAt: Date.now() },
    ]);
    runtime.saveSession(workspaceRoot, session);
    sendPetEvent({ type: 'say', text: result.text });
    return { sessionId: sessionId, text: result.text };
  });
}

async function handleBridgeRequest(req, res) {
  if (bridgeRateLimited(req)) return bridgeJson(res, 429, { error: 'rate limit exceeded' });
  if (!bridgeAuthorized(req)) return bridgeJson(res, 401, { error: 'unauthorized' });

  const url = new URL(req.url, 'http://127.0.0.1');
  if (req.method === 'GET' && url.pathname === '/v1/health') {
    return bridgeJson(res, 200, { ok: true, app: APP_NAME });
  }
  if (req.method === 'GET' && url.pathname === '/v1/pet/state') {
    const bounds = petWindow && !petWindow.isDestroyed() ? petWindow.getBounds() : null;
    return bridgeJson(res, 200, {
      app: APP_NAME,
      visible: !!(petWindow && !petWindow.isDestroyed() && petWindow.isVisible()),
      actionId: petActionId,
      actions: Object.keys(HAS_ACTION),
      bounds,
    });
  }
  if (req.method !== 'POST') return bridgeJson(res, 405, { error: 'method not allowed' });

  let body;
  try { body = await bridgeReadBody(req); } catch (e) {
    if (!res.headersSent && !res.destroyed) bridgeJson(res, 400, { error: e.message });
    return;
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return bridgeJson(res, 400, { error: 'JSON object required' });
  }

  if (url.pathname === '/v1/pet/action') {
    const actionId = String(body.actionId || '');
    if (!HAS_ACTION[actionId]) return bridgeJson(res, 400, { error: 'unknown actionId' });
    if (!petWindow || petWindow.isDestroyed()) return bridgeJson(res, 503, { error: 'pet window is unavailable' });
    petWindow.webContents.send('switch-action', actionId);
    return bridgeJson(res, 200, { ok: true, actionId: actionId });
  }
  if (url.pathname === '/v1/pet/say') {
    const text = String(body.text || '').trim();
    if (!text) return bridgeJson(res, 400, { error: 'text is required' });
    if (text.length > 500) return bridgeJson(res, 400, { error: 'text cannot exceed 500 characters' });
    if (!petWindow || petWindow.isDestroyed()) return bridgeJson(res, 503, { error: 'pet window is unavailable' });
    const event = { type: 'say', text: text };
    if (body.actionId != null) {
      const actionId = String(body.actionId);
      if (!HAS_ACTION[actionId]) return bridgeJson(res, 400, { error: 'unknown actionId' });
      event.actionId = actionId;
    }
    sendPetEvent(event);
    return bridgeJson(res, 200, { ok: true });
  }
  if (url.pathname === '/v1/chat') {
    try { return bridgeJson(res, 200, await bridgeChat(body)); }
    catch (e) { return bridgeJson(res, 502, { error: String(e && e.message ? e.message : e) }); }
  }
  return bridgeJson(res, 404, { error: 'not found' });
}

function startBridge() {
  if (!bridgeToken) {
    console.log('[bridge] disabled; set ISLA_BRIDGE_TOKEN to enable the local API');
    return;
  }
  if (Buffer.byteLength(bridgeToken) < 32) {
    console.error('[bridge] ISLA_BRIDGE_TOKEN must contain at least 32 bytes');
    return;
  }
  if (!Number.isInteger(bridgePort) || bridgePort < 1024 || bridgePort > 65535) {
    console.error('[bridge] invalid ISLA_BRIDGE_PORT; expected 1024..65535');
    return;
  }
  bridgeServer = http.createServer(function (req, res) {
    handleBridgeRequest(req, res).catch(function (e) {
      if (!res.headersSent && !res.destroyed) bridgeJson(res, 500, { error: 'internal error' });
      logError('bridge-request', e);
    });
  });
  bridgeServer.on('error', function (e) { logError('bridge-server', e); });
  bridgeServer.listen(bridgePort, '127.0.0.1', function () {
    console.log('[bridge] listening on http://127.0.0.1:' + bridgePort);
  });
}

// ---- 实时日期天气（date-weather 动作播报用）----
// 主进程拉取：ip-api.com 定位 + open-meteo.com 取当前天气（都无需 key），
// 缓存 10 分钟；任一环节失败返回 null，渲染层只显示日期
let weatherCache = { at: 0, data: null };
async function fetchWeather() {
  const now = Date.now();
  if (now - weatherCache.at < 10 * 60 * 1000) return weatherCache.data;
  try {
    const locResp = await fetch('http://ip-api.com/json/?lang=zh-CN', { signal: AbortSignal.timeout(6000) });
    const loc = await locResp.json();
    if (loc.status !== 'success' || !loc.lat || !loc.lon) throw new Error('ip-api 定位失败');
    const city = (loc.city || loc.regionName || '').trim(); // 气泡空间小，只取城市名（直辖市等 city 为空时退回地区名）
    const wResp = await fetch(
      'https://api.open-meteo.com/v1/forecast?latitude=' + loc.lat + '&longitude=' + loc.lon +
        '&current=temperature_2m,weather_code&timezone=auto',
      { signal: AbortSignal.timeout(6000) }
    );
    const w = await wResp.json();
    const cur = w && w.current;
    if (!cur || typeof cur.temperature_2m !== 'number') throw new Error('天气数据缺失');
    weatherCache = { at: now, data: { city: city.trim(), temp: Math.round(cur.temperature_2m), code: cur.weather_code } };
    return weatherCache.data;
  } catch (e) {
    console.warn('[pet] 天气获取失败：', e && e.message ? e.message : e);
    return null;
  }
}
ipcMain.handle('weather-get', fetchWeather);

ipcMain.on('set-opacity', function (_event, v) {
  setOpacity(v);
});

ipcMain.on('quit-app', function () {
  app.quit();
});

// ---- global shortcuts ----
function registerShortcuts() {
  const SHORTCUTS = [
    ['Ctrl+Shift+B', toggleVisible],
    ['Ctrl+Shift+Left', function () { sendCommand('zoom-out'); }],
    ['Ctrl+Shift+Right', function () { sendCommand('zoom-in'); }],
    ['Ctrl+Shift+Up', function () { setOpacity(settings.opacity + 0.1); }],
    ['Ctrl+Shift+Down', function () { setOpacity(settings.opacity - 0.1); }],
    ['Ctrl+Shift+R', resetPosition],
    ['Ctrl+Shift+A', createChatWindow],
    ['Ctrl+Shift+Q', function () { app.quit(); }],
  ];
  for (const pair of SHORTCUTS) {
    if (!globalShortcut.register(pair[0], pair[1])) {
      console.warn('[pet] 快捷键注册失败（可能被其他程序占用）：' + pair[0]);
    }
  }
}

// ---- app lifecycle ----
app.whenReady().then(function () {
  try {
    logStep('ready');
    createWindow();
    logStep('window-created');
    createTray();
    startBridge();
    initInputCapture();
    registerShortcuts();
    logStep('startup-complete');
    screen.on('display-added', checkDisplayChange);
    screen.on('display-removed', checkDisplayChange);
    screen.on('display-metrics-changed', checkDisplayChange);
    app.on('activate', function () {
      if (BrowserWindow.getAllWindows().length === 0) createWindow();
    });
  } catch (e) {
    logError('whenReady', e);
  }
});

app.on('before-quit', function () {
  // 先隐藏并销毁所有窗口 + 托盘，再收尾，避免 alt+tab/任务栏残留幽灵条目
  // （uiohook 钩子不手动 stop：进程退出时系统自动释放，stop() 会拖慢甚至卡住退出）
  try { if (tray) tray.destroy(); } catch (e) { /* ignore */ }
  [petWindow].forEach(function (win) {
    try {
      if (win && !win.isDestroyed()) { win.hide(); win.destroy(); }
    } catch (e) { /* ignore */ }
  });
  globalShortcut.unregisterAll();
  if (bridgeServer) {
    try { bridgeServer.close(); } catch (e) { /* ignore */ }
    bridgeServer = null;
  }
  if (pendingSettingsSave) {
    clearTimeout(pendingSettingsSave);
    pendingSettingsSave = null;
  }
  try {
    fs.mkdirSync(userDataDir, { recursive: true });
    fs.writeFileSync(path.join(userDataDir, 'settings.json'), JSON.stringify(settings, null, 2));
  } catch (e) { /* ignore */ }
});

app.on('window-all-closed', function () {
  app.quit();
});
